export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";

interface Env extends AuditMaintenanceEnv {
  ALERT_EMAIL_WEBHOOK?: string;
}

export default {
  fetch(request, env, context) {
    return openNextWorker.fetch(request, env, context);
  },
  scheduled(controller, env, context) {
    context.waitUntil(
      runAuditMaintenance(env, new Date(controller.scheduledTime)).catch(async (error) => {
        const message = error instanceof Error ? error.message : "Unknown audit maintenance failure";
        await alert(env, "Audit snapshot failed", message);
        throw error;
      }),
    );
  },
} satisfies ExportedHandler<Env>;
